{
"css": "/* Identity Section Spacing & Layout */
.product-identity {
  padding-top: 24px;
  padding-bottom: 24px;
}

@media (min-width: 701px) {
  .product-identity {
    padding-top: 0;
  }
}

/* Eyebrow */
.product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  margin-bottom: 8px;
}

/* Title */
.product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: #202024;
  margin: 0;
}

@media (min-width: 701px) {
  .product-identity .title {
    font-size: 28px;
  }
}

/* Price Row */
.product-identity .price-row {
  margin-top: 12px;
  margin-bottom: 24px;
}

.product-identity .price {
  display: block;
  font-size: 24px;
  font-weight: 800;
  color: #202024;
}

/* Metadata */
.product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 24px;
}

.product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  flex-shrink: 0;
}

.product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: #555560;
  white-space: nowrap;
}

/* Description */
.product-identity .description {
  margin-top: 20px;
  font-size: 15px;
  line-height: 1.75;
  color: #202024;
  margin-bottom: 0;
}"
}
